import sys
import os
import argparse
import sqlite3
import csv
import json
import gzip
import bz2
import lzma
import re

def guess_format(filename):
    if filename == "-":
        return "csv"
    ext = os.path.splitext(filename)[1].lower()
    if ext == ".csv": return "csv"
    if ext == ".ltsv": return "ltsv"
    if ext == ".json": return "json"
    if ext == ".jsonl": return "jsonl"
    if ext == ".yaml" or ext == ".yml": return "yaml"
    if ext == ".tbln": return "tbln"
    return "csv"

def load_file(conn, filename, args):
    original_name = filename
    table_name = filename

    jq_expr = None
    if "::" in filename:
        filename, jq_expr = filename.split("::", 1)

    if args.ijq:
        jq_expr = args.ijq

    if filename == "-":
        f = sys.stdin
    else:
        if not os.path.exists(filename):
            return None
        if filename.endswith(".gz"):
            f = gzip.open(filename, "rt")
        elif filename.endswith(".bz2"):
            f = bz2.open(filename, "rt")
        elif filename.endswith(".xz"):
            f = lzma.open(filename, "rt")
        else:
            f = open(filename, "r")

    fmt = guess_format(filename)
    if args.icsv: fmt = "csv"
    if args.ijson: fmt = "json"
    if args.iltsv: fmt = "ltsv"
    if args.iyaml: fmt = "yaml"
    if args.itbln: fmt = "tbln"

    rows = []
    if fmt == "csv":
        # We need to handle the delimiter. args.id might be a literal semicolon.
        delimiter = args.id
        if delimiter == "\\t": delimiter = "\t"
        reader = csv.reader(f, delimiter=delimiter)
        for i, row in enumerate(reader):
            if i < args.is_: continue
            rows.append(row)
            if args.ilr > 0 and len(rows) >= args.ilr + (1 if args.ih else 0):
                break
    elif fmt == "json":
        try:
            data = json.load(f)
            if jq_expr:
                parts = [p for p in jq_expr.split(".") if p]
                for part in parts:
                    if isinstance(data, dict) and part in data:
                        data = data[part]
                    elif isinstance(data, list) and part.isdigit():
                        data = data[int(part)]
                    else:
                        data = None
                        break
            if isinstance(data, list):
                for item in data:
                    if isinstance(item, dict):
                        rows.append(item)
                    else:
                        rows.append([item])
            elif isinstance(data, dict):
                rows.append(data)
        except:
            pass
    elif fmt == "ltsv":
        for i, line in enumerate(f):
            if i < args.is_: continue
            parts = line.strip().split("\t")
            row = {}
            for part in parts:
                if ":" in part:
                    k, v = part.split(":", 1)
                    row[k] = v
            rows.append(row)
            if args.ilr > 0 and len(rows) >= args.ilr: break

    if not rows:
        return None

    header = []
    if args.ih and isinstance(rows[0], (list, tuple)):
        header = [str(h) for h in rows[0]]
        rows = rows[1:]
    elif isinstance(rows[0], dict):
        # Collect all keys from all rows? trdsql seems to use keys from the first row.
        header = list(rows[0].keys())
        new_rows = []
        for r in rows:
            new_rows.append([r.get(h, None) for h in header])
        rows = new_rows
    else:
        header = ["c" + str(i+1) for i in range(len(rows[0]))]

    if args.inull:
        for i in range(len(rows)):
            for j in range(len(rows[i])):
                if str(rows[i][j]) == args.inull:
                    rows[i][j] = None

    col_defs = ", ".join(['"{}" TEXT'.format(h) for h in header])
    conn.execute('DROP TABLE IF EXISTS "{}"'.format(table_name))
    conn.execute('CREATE TABLE "{}" ({})'.format(table_name, col_defs))
    placeholders = ", ".join(["?"] * len(header))
    conn.executemany('INSERT INTO "{}" VALUES ({})'.format(table_name, placeholders), rows)
    return table_name

def output_results(columns, rows, args):
    if args.inum:
        columns = ["num"] + list(columns)
        rows = [(i+1,) + row for i, row in enumerate(rows)]

    if args.onull:
        new_rows = []
        for row in rows:
            new_rows.append([ (args.onull if v is None else v) for v in row])
        rows = new_rows
    else:
        # Standard trdsql behavior: nulls are empty strings in CSV/LTSV
        new_rows = []
        for row in rows:
            new_rows.append([ ("" if v is None else v) for v in row])
        rows = new_rows

    out_f = sys.stdout
    if args.out:
        if args.oz == "gz":
            out_f = gzip.open(args.out, "wt")
        elif args.oz == "bz2":
            out_f = bz2.open(args.out, "wt")
        elif args.oz == "xz":
            out_f = lzma.open(args.out, "wt")
        else:
            out_f = open(args.out, "w")

    if args.ojson:
        res = []
        for row in rows:
            res.append(dict(zip(columns, [str(v) if v is not None else None for v in row])))
        out_f.write(json.dumps(res, indent=2) + "\n")
    elif args.ojsonl:
        for row in rows:
            out_f.write(json.dumps(dict(zip(columns, [str(v) if v is not None else None for v in row])), separators=(',', ':')) + "\n")
    elif args.oltsv:
        for row in rows:
            out_f.write("\t".join(["{}:{}".format(k, v) for k, v in zip(columns, row)]) + "\n")
    elif args.oat:
        print_table(columns, rows, out_f)
    elif args.omd:
        print_markdown(columns, rows, out_f)
    elif args.ovf:
        print_vertical(columns, rows, out_f)
    elif args.otbln:
        print_tbln(columns, rows, out_f)
    else:
        delimiter = args.od
        if delimiter == "\\t": delimiter = "\t"
        writer = csv.writer(out_f, delimiter=delimiter, lineterminator='\r\n' if args.ocrlf else '\n', quoting=csv.QUOTE_ALL if args.oaq else csv.QUOTE_MINIMAL, quotechar=args.oq)
        if args.oh:
            writer.writerow(columns)
        for row in rows:
            writer.writerow(row)

    if out_f != sys.stdout:
        out_f.close()

def print_table(columns, rows, out_f):
    if not columns: return
    widths = [len(str(c)) for c in columns]
    for row in rows:
        for i, v in enumerate(row):
            widths[i] = max(widths[i], len(str(v)))

    sep = "+" + "+".join(["-" * (w + 2) for w in widths]) + "+"
    out_f.write(sep + "\n")
    out_f.write("| " + " | ".join([str(c).ljust(widths[i]) for i, c in enumerate(columns)]) + " |\n")
    out_f.write(sep + "\n")
    for row in rows:
        out_f.write("| " + " | ".join([str(v).ljust(widths[i]) for i, v in enumerate(row)]) + " |\n")
    out_f.write(sep + "\n")

def print_markdown(columns, rows, out_f):
    if not columns: return
    widths = [len(str(c)) for c in columns]
    for row in rows:
        for i, v in enumerate(row):
            widths[i] = max(widths[i], len(str(v)))
    out_f.write("| " + " | ".join([str(c).ljust(widths[i]) for i, c in enumerate(columns)]) + " |\n")
    out_f.write("|" + "|".join(["-" * (w + 2) for w in widths]) + "|\n")
    for row in rows:
        out_f.write("| " + " | ".join([str(v).ljust(widths[i]) for i, v in enumerate(row)]) + " |\n")

def print_vertical(columns, rows, out_f):
    if not rows: return
    max_w = max([len(str(c)) for c in columns])
    for i, row in enumerate(rows):
        out_f.write("---[ {}]------------------------\n".format(i + 1))
        for k, v in zip(columns, row):
            out_f.write("{} | {}\n".format(str(k).rjust(max_w), v))

def print_tbln(columns, rows, out_f):
    out_f.write("; name: | " + " | ".join(columns) + " |\n")
    out_f.write("; type: | " + " | ".join(["text"] * len(columns)) + " |\n")
    for row in rows:
        out_f.write("| " + " | ".join([str(v) for v in row]) + " |\n")

