    parser.add_argument("-otbln", action="store_true")
    parser.add_argument("-oyaml", action="store_true")
    parser.add_argument("-id", default=",")
    parser.add_argument("-od", default=",")
    parser.add_argument("-oq", default='"')
    parser.add_argument("-is", dest="is_", type=int, default=0)
    parser.add_argument("-ilr", type=int, default=0)
    parser.add_argument("-inull")
    parser.add_argument("-onull")
    parser.add_argument("-inum", action="store_true")
    parser.add_argument("-t")
