    potential_tables = re.findall(r'([a-zA-Z0-9_\-\./]+(?:::[a-zA-Z0-9_\-\./\(\)\[\]]+)?)', sql)
    loaded_tables = set()
    for t in potential_tables:
        if ("." in t or t == "-" or "::" in t) and t not in loaded_tables:
            if load_file(conn, t, args):
                loaded_tables.add(t)
    if args.t and args.t not in loaded_tables:
        if load_file(conn, args.t, args):
            loaded_tables.add(args.t)

    # Sort loaded_tables by length descending to avoid partial replacement of longer names
    for t in sorted(list(loaded_tables), key=len, reverse=True):
        sql = re.sub(r'(?<!["`\'])\b' + re.escape(t) + r'\b(?!["`\'])', '"{}"'.format(t), sql)

    try:
        cursor = conn.cursor()
        for query in sql.split(";"):
            query = query.strip()
            if not query: continue
            cursor.execute(query)
            if cursor.description:
                columns = [d[0] for d in cursor.description]
                rows = cursor.fetchall()
                output_results(columns, rows, args)
    except Exception as e:
        sys.stderr.write(str(e) + "\n")
        sys.exit(1)

if __name__ == "__main__":
    main()
